def isMonotonic(A):
    def isIncreasing(A):
        for i in range(1, len(A)):
            if A[i] < A[i - 1]:
                return False
        return True

    def isDecreasing(A):
        for i in range(1, len(A)):
            if A[i] > A[i - 1]:
                return False
        return True

    return isIncreasing(A) or isDecreasing(A)
```
